// === Tab: mySketch ===
let N = 800;
let distval = 45;
let dt = 0.15;
let rad = 200.0;
let nconMax = 5;
let quiescent = 180;
let warptime = 50;

let particle = new Array(N);
color[] [] col = { {"#00ce39", "#2274a5", "#f75c03", "#f1c40", "#d90368"}, 
                    {"#1f2426", "#960200", "#ce6c47", "#ffd046", "#eadaa2"}, 
                    {"#780116", "#f7b538", "#780116", "#db7c26", "#1f2426"}, 
                    {"#1f2426", "#fbfff1", "#3d52d5", "#090c9b", "#3c3744"} };
let cind = 0;
let indx = 1;
let wp = 0;
let type = 1;
let frac = N/2;

function setup() {
  createCanvas(1024, 768);
  background(25);

  for (i=0; i<N; ++i) {
  	particle[i] = new particles();
  }
}

function draw() {	
  //-- I've put all the particle operations inside another function called updateParticles, so let can play with different dynamics
  if (type==0){ 
    updateParticles();
  } else {
    if (wp<warptime){
      updateParticlesWarp(frac);
      wp++;
    } else {
      type = 0;
      wp = 0;
    }
  }

  if (indx%quiescent==0) {
    type = 1;
    noStroke();
    fill(25,225);
    rect(0,0,width,height);
    frac = int(random(20,N-20));
  } 
  indx++;
}

function updateParticles() {  
  noStroke();
  fill(25,60);
  rect(0,0,width,height);

  for (i=0; i<N; ++i) {
    particle[i].display(75);
    particle[i].move(0.15);
    particle[i].updateVelocity(random(2,4));
    //particle[i].checkPeriodicityCircle();
    particle[i].checkPeriodicity();
    particle[i].phase += random(-1.0,1.0)*0.25;
    particle[i].ncon = 0;
  }
  connect();

  //--  let circle
  //noFill();
  //stroke(255,25);
  //strokeWeight(0.5);
  //ellipse(width/2,height/2,rad*2,rad*2);
}

function updateParticlesWarp(fr) {
  noStroke();
  fill(25,40);
  rect(0,0,width,height);

  for (i=0; i<fr; ++i) {
