    //} else if (flag==1){
    //  particle[i].vel.x = 0;
    //  particle[i].vel.y *= 2.0;
    //}
    particle[i].vel.y = 0;
    particle[i].vel.x *= random(1.0,2.5);
    particle[i].display(175);
    particle[i].move(0.25);
    particle[i].updateVelocity(random(20,30));
