}

function mousePressed() {
  cind = (cind+1)%4;
  for (i=0; i<N; ++i) {
    particle[i].rang = col[cind][int(random(5))];
  }

}


// === Tab: tab2 ===

class particles{
  loc;
  vel;
  acc;
  phase;
  ncon;
  rang;

  constructor(){
    loc = new PVector(random(width/2-50,width/2+50),random(height/2-50,height/2+50));
    vel = new PVector( 0.0,0.0 );
    acc = new PVector( 0.0,0.0 );
    phase = random(0.0,10.0);
    ncon = 0;
    rang =col[cind][int(random(5))];
  }

  function display(alpha) {
    noStroke();
    fill(rang,alpha);
    ellipse(loc.x, loc.y, 3, 3);
  }

  function move(dtval) {
    loc.add(PVector.mult(vel,dtval));
  }

  function updateVelocity(len) {
    vel.x = cos( phase ) * len;
    vel.y = sin( phase ) * len;
  }

  function checkPeriodicity() {
    loc.x = (loc.x+width)%width;
    loc.y = (loc.y+height)%height;
  }

  function checkPeriodicityCircle() {
    if ( pow((loc.x-width/2.0),2.0) + pow((loc.y-height/2.0),2.0) > rad*rad ){
      loc.x = width/2.0 + random(-20,20);
      loc.y = height/2.0 + random(-20,20);
    }
  }

}

function connect() {
  for (i=0; i<N; ++i) {
    for (j=0; j<N; ++j) {
      if (i!=j) {
        let dist = pow( (particle[i].loc.x - particle[j].loc.x),2.0 ) + pow( (particle[i].loc.y - particle[j].loc.y),2.0 ) ;
        if ( (dist < distval*distval) && (particle[i].ncon<nconMax) && (particle[j].ncon<nconMax) ){
            stroke(particle[i].rang);
            strokeWeight(1);
            line(particle[i].loc.x, particle[i].loc.y, particle[j].loc.x, particle[j].loc.y);
            particle[i].ncon++;
            particle[j].ncon++;
        }
      }
    }
  }
}

